using System;using System.Collections.Generic;using System.IO;using System.Linq;using UnityEngine;
namespace EarthUnscripted
{
 // Focused XZ admission for a pair of same-layer roads. The only ignored overlap
 // is inside explicit shared-node cores; connectivity alone never suppresses it.
 public static class RoadParallelClearance
 {
  public sealed class Result{public bool Applicable,Admitted;public double OutsideCoreOverlapArea;public int TrianglePairs,IntersectingPairs,SharedPlaneCorePairs;public string Reason;}
  struct P{public double X,Z;public P(double x,double z){X=x;Z=z;}}
  static double Cross(P a,P b,P p)=>(b.X-a.X)*(p.Z-a.Z)-(b.Z-a.Z)*(p.X-a.X);
  static double Area(IReadOnlyList<P> r){double a=0;for(int i=0;i<r.Count;i++){var b=r[(i+1)%r.Count];a+=r[i].X*b.Z-b.X*r[i].Z;}return a*.5;}
  static List<P> Intersection(Vector3[] a,Vector3[] b){var p=a.Select(v=>new P(v.x,v.z)).ToList();var ring=b.Select(v=>new P(v.x,v.z)).ToArray();double sign=Math.Sign(Area(ring));for(int edge=0;edge<3&&p.Count>0;edge++){var output=new List<P>();var previous=p[p.Count-1];double before=Cross(ring[edge],ring[(edge+1)%3],previous)*sign;foreach(var next in p){double after=Cross(ring[edge],ring[(edge+1)%3],next)*sign;bool old=before>=0,current=after>=0;if(old!=current){double t=before/(before-after);output.Add(new P(previous.X+(next.X-previous.X)*t,previous.Z+(next.Z-previous.Z)*t));}if(current)output.Add(next);previous=next;before=after;}p=output;}return p;}
  sealed class Triangle{public Vector3[] Points;public double[] Source;}
  static List<Triangle> Triangles(GeoRoad road,RoadMarkingPlan.RoadFrame frame,float width,IReadOnlyList<RoadJunctionPatchDto> cores,bool bevelAll=false)
  {
   var result=new List<Triangle>();var metric=new RoadElevationMetric(road);var adapter=new RoadElevationHorizontalFrame(metric,frame);var stops=new SortedSet<double>{0,metric.SourceLength};for(int i=1;i<metric.PointCount;i++)stops.Add(metric.SourceAtPoint(i));foreach(var patch in cores)foreach(var arm in patch.arms)if(arm.roadId==road.id){stops.Add(Math.Max(0,Math.Min(metric.SourceLength,arm.sourceDistance)));stops.Add(Math.Max(0,Math.Min(metric.SourceLength,arm.sourceDistance+arm.direction*arm.coreLength)));}var knots=stops.ToArray();for(int i=1;i<knots.Length;i++){double start=knots[i-1],end=knots[i];int steps=Math.Max(1,(int)Math.Ceiling((end-start)/2.5));for(int j=0;j<steps;j++){double a=start+(end-start)*j/steps,b=start+(end-start)*(j+1)/steps;adapter.At(a,out var p,out var rp,out _,out _,false,bevelAll);adapter.At(b,out var q,out var rq,out _,out _,true,bevelAll);var al=p-rp*width*.5f;var ar=p+rp*width*.5f;var bl=q-rq*width*.5f;var br=q+rq*width*.5f;al.y=ar.y=bl.y=br.y=0;foreach(var t in new[]{new Triangle{Points=new[]{al,bl,ar},Source=new[]{a,b,a}},new Triangle{Points=new[]{ar,bl,br},Source=new[]{a,b,b}}}){if(Vector3.Cross(t.Points[1]-t.Points[0],t.Points[2]-t.Points[0]).y<=1e-8){if(!bevelAll)return Triangles(road,frame,width,cores,true);throw new InvalidDataException("Unsupported folded bevel corridor "+road.id+" source="+a+".."+b);}result.Add(t);}}}
   foreach(double s in (bevelAll?Enumerable.Range(1,metric.PointCount-2).Select(metric.SourceAtPoint):frame.SharpDistances)){adapter.At(s,out var p,out _,out _,out _,false,bevelAll);p.y=0;for(int i=0;i<32;i++){double a=i*Math.PI/16,b=(i+1)*Math.PI/16;var x=p+new Vector3((float)Math.Cos(a),0,(float)Math.Sin(a))*width*.5f;var y=p+new Vector3((float)Math.Cos(b),0,(float)Math.Sin(b))*width*.5f;result.Add(new Triangle{Points=new[]{p,y,x},Source=new[]{s,s,s}});}}
   if(result.Count>8192)throw new InvalidDataException("Corridor pair triangle budget");return result;
  }
  static double Station(P p,Triangle t){var a=t.Points[0];var b=t.Points[1];var c=t.Points[2];double ax=(double)a.x-c.x,az=(double)a.z-c.z,bx=(double)b.x-c.x,bz=(double)b.z-c.z,px=p.X-c.x,pz=p.Z-c.z,den=bz*ax-bx*az,u=(bz*px-bx*pz)/den,v=(-az*px+ax*pz)/den;return u*t.Source[0]+v*t.Source[1]+(1-u-v)*t.Source[2];}
  static bool SharedPlane(List<P> ring,Triangle a,Triangle b,GeoRoad ar,GeoRoad br,IReadOnlyList<RoadJunctionPatchDto> cores)
  {foreach(var p in cores){bool Inside(RoadJunctionArmDto arm,Triangle t){foreach(var point in ring){double d=arm.direction*(Station(point,t)-arm.sourceDistance);if(d<-.00001||d>arm.coreLength+.00001)return false;}return true;}if(p.arms.Any(arm=>arm.roadId==ar.id&&Inside(arm,a))&&p.arms.Any(arm=>arm.roadId==br.id&&Inside(arm,b)))return true;}return false;}
  public static Result Check(GeoRoad a,GeoRoad b,float widthA,float widthB,IReadOnlyList<RoadJunctionPatchDto> sharedCores)
  {
   if(a.layer!=b.layer||a.bridge!=b.bridge||a.tunnel!=b.tunnel)return new Result{Applicable=false,Admitted=false,Reason="Grade-separated pair needs explicit structural clearance, not at-grade union"};if(widthA<2||widthA>80||widthB<2||widthB>80)throw new InvalidDataException("Corridor widths");var frames=RoadMarkingPlan.Build(new[]{a,b});var aa=Triangles(a,frames.Frames[a.id],widthA,sharedCores);var bb=Triangles(b,frames.Frames[b.id],widthB,sharedCores);if((long)aa.Count*bb.Count>1000000)throw new InvalidDataException("Corridor pair work budget");
   var cores=new List<RoadBankExteriorClip.Footprint>();foreach(var patch in sharedCores){if(patch.layer!=a.layer||!patch.arms.Any(x=>x.roadId==a.id)||!patch.arms.Any(x=>x.roadId==b.id))throw new InvalidDataException("Unbound shared core");cores.Add(new RoadBankExteriorClip.Footprint{Id=patch.id,Layer=patch.layer,Polygon=patch.boundary});}
   var result=new Result{Applicable=true};foreach(var xx in aa)foreach(var yy in bb){var x=xx.Points;var y=yy.Points;result.TrianglePairs++;if(x.Max(p=>p.x)<y.Min(p=>p.x)||x.Min(p=>p.x)>y.Max(p=>p.x)||x.Max(p=>p.z)<y.Min(p=>p.z)||x.Min(p=>p.z)>y.Max(p=>p.z))continue;var ring=Intersection(x,y);if(ring.Count<3||Math.Abs(Area(ring))<1e-10)continue;result.IntersectingPairs++;if(SharedPlane(ring,xx,yy,a,b,sharedCores)){result.SharedPlaneCorePairs++;continue;}for(int i=1;i<ring.Count-1;i++){Vector3 V(P p)=>new Vector3((float)p.X,0,(float)p.Z);var exterior=RoadBankExteriorClip.Clip(new[]{V(ring[0]),V(ring[i]),V(ring[i+1])},a.layer,false,cores);for(int t=0;t<exterior.Triangles.Length;t+=3){var A=exterior.Vertices[exterior.Triangles[t]];var B=exterior.Vertices[exterior.Triangles[t+1]];var C=exterior.Vertices[exterior.Triangles[t+2]];result.OutsideCoreOverlapArea+=Math.Abs(((double)B.x-A.x)*((double)C.z-A.z)-((double)B.z-A.z)*((double)C.x-A.x))*.5;}}}
   result.Admitted=result.OutsideCoreOverlapArea<=1e-6;result.Reason=result.Admitted?"Pair XZ separation outside declared shared cores proved; core vertical authority separately required":"Parallel pavement overlap outside shared cores";return result;
  }
 }
}
